int read_7z_substream_info(struct archive_read *a, struct _7z_substream_info *ss,
                           struct _7z_folder *f, size_t numFolders) {
  size_t i, j;
  int res = 0;

  ss->num_unpack_streams = 0;
  ss->unpack_sizes = NULL;
  ss->digests = NULL;

  for (i = 0; i < numFolders; ++i) {
    ss->num_unpack_streams += f[i].num_unpack_streams;
  }

  ss->unpack_sizes = (size_t *)malloc(ss->num_unpack_streams * sizeof(size_t));
  ss->digests = (uint32_t *)malloc(ss->num_unpack_streams * sizeof(uint32_t));
  if (ss->unpack_sizes == NULL || ss->digests == NULL) {
    res = -1;
    goto cleanup;
  }

  for (i = 0; i < numFolders; ++i) {
    for (j = 0; j < f[i].num_unpack_streams; ++j) {
      if (archive_read_has_new_data(a)) {
        res = -1;
        goto cleanup;
      }
      size_t size;
      if (archive_read_data(a, &size, sizeof(size_t)) != sizeof(size_t)) {
        res = -1;
        goto cleanup;
      }
      ss->unpack_sizes[i * f[i].num_unpack_streams + j] = size;

      uint32_t digest;
      if (archive_read_data(a, &digest, sizeof(uint32_t)) != sizeof(uint32_t)) {
        res = -1;
        goto cleanup;
      }
      ss->digests[i * f[i].num_unpack_streams + j] = digest;
    }
  }

  if (res == 0 && a->archive.archive_type != 'kEnd') {
    res = -1;
  }

cleanup:
  if (res != 0) {
    free(ss->unpack_sizes);
    ss->unpack_sizes = NULL;
    free(ss->digests);
    ss->digests = NULL;
  }

  return res;
}

int read_7z_substream_info(struct archive_read *a, struct _7z_substream_info *ss,
                           struct _7z_folder *f, size_t numFolders) {
  size_t i, j;
  int r;

  ss->num_unpack_streams = 0;
  ss->unpack_sizes = NULL;
  ss->digests = NULL;

  for (i = 0; i < numFolders; ++i) {
    if (f[i].num_unpack_streams > ss->num_unpack_streams)
      ss->num_unpack_streams = f[i].num_unpack_streams;
  }

  ss->unpack_sizes = (uint64_t *)malloc(ss->num_unpack_streams * sizeof(uint64_t));
  ss->digests = (uint32_t *)malloc(ss->num_unpack_streams * sizeof(uint32_t));

  if (!ss->unpack_sizes || !ss->digests) {
    free(ss->unpack_sizes);
    free(ss->digests);
    return -1;
  }

  for (i = 0; i < numFolders; ++i) {
    for (j = 0; j < f[i].num_unpack_streams; ++j) {
      r = archive_read_data(a, &ss->unpack_sizes[j], sizeof(uint64_t));
      if (r != (int)sizeof(uint64_t))
        return -1;

      r = archive_read_data(a, &ss->digests[j], sizeof(uint32_t));
      if (r != (int)sizeof(uint32_t))
        return -1;
    }
  }

  {
    uint32_t type;
    r = archive_read_data(a, &type, sizeof(uint32_t));
    if (r != (int)sizeof(uint32_t) || type != kEnd)
      return -1;
  }

  return 0;
}

int _7z_read_substream_info(struct archive_read *a, struct _7z_substream_info *ss, struct _7z_folder *f, size_t numFolders) {
  int i;
  int ret = 0;
  size_t numUnpackStreams;

  ss->num_unpacked_streams = 0;
  ss->unpack_pos = 0;
  ss->digests = NULL;
  ss->digests_size = 0;

  for (i = 0; i < numFolders; ++i) {
    numUnpackStreams = f[i].num_unpack_streams;
    if (numUnpackStreams > ss->num_unpacked_streams) {
      void *new_sizes;
      void *new_digests;

      new_sizes = (void *)realloc(ss->sizes, numUnpackStreams * sizeof(*ss->sizes));
      if (new_sizes == NULL) {
        ret = -1;
        goto cleanup;
      }
      ss->sizes = new_sizes;

      new_digests = (void *)realloc(ss->digests, numUnpackStreams * sizeof(*ss->digests));
      if (new_digests == NULL) {
        ret = -1;
        goto cleanup;
      }
      ss->digests = new_digests;

      ss->num_unpacked_streams = numUnpackStreams;
    }

    for (size_t j = 0; j < numUnpackStreams; ++j) {
      int64_t size;
      if (f[i].unpack_info.read(a, &size, j) != 0) {
        ret = -1;
        goto cleanup;
      }

      ss->sizes[j] = size;
    }

    if (f[i].has_digests) {
      for (size_t j = 0; j < numUnpackStreams; ++j) {
        if (f[i].unpack_info.read_digest(a, &ss->digests[j]) != 0) {
          ret = -1;
          goto cleanup;
        }
      }
    }
  }

  if (f[numFolders - 1].unpack_info.read(a, &ss->last_type, 0) != 0) {
    ret = -1;
    goto cleanup;
  }

  if (ss->last_type != kEnd) {
    ret = -1;
    goto cleanup;
  }

cleanup:
  return ret;
}

int read_7z_substream_info(struct archive_read *a, struct _7z_substream_info *ss, struct _7z_folder *f, size_t numFolders) {
    size_t i;
    int ret;

    ss->numFolders = numFolders;
    ss->numUnpackStreams = 0;

    for (i = 0; i < numFolders; ++i) {
        ss->numUnpackStreams += f[i].numUnpackStreams;
    }

    ss->unpackSizes = (uint64_t *)malloc(ss->numUnpackStreams * sizeof(uint64_t));
    if (!ss->unpackSizes)
        return -1;

    ss->digests = (uint32_t *)malloc(ss->numUnpackStreams * sizeof(uint32_t));
    if (!ss->digests) {
        free(ss->unpackSizes);
        return -1;
    }

    for (i = 0; i < numFolders; ++i) {
        size_t j;
        for (j = 0; j < f[i].numUnpackStreams; ++j) {
            ret = archive_read_read(a, &ss->unpackSizes[ss->numUnpackStreams - f[i].numUnpackStreams + j], sizeof(uint64_t));
            if (ret != sizeof(uint64_t)) {
                free(ss->unpackSizes);
                free(ss->digests);
                return -1;
            }

            ret = archive_read_read(a, &ss->digests[ss->numUnpackStreams - f[i].numUnpackStreams + j], sizeof(uint32_t));
            if (ret != sizeof(uint32_t)) {
                free(ss->unpackSizes);
                free(ss->digests);
                return -1;
            }
        }
    }

    ret = archive_read_read(a, &ss->finalType, sizeof(ss->finalType));
    if (ret != sizeof(ss->finalType)) {
        free(ss->unpackSizes);
        free(ss->digests);
        return -1;
    }

    if (ss->finalType != kEnd) {
        free(ss->unpackSizes);
        free(ss->digests);
        return -1;
    }

    return 0;
}
